input.content:
// Delivers webhook events to billing-provider.
//
// Delivery retries transient failures so intermittent 502s and network
// hiccups from billing-provider no longer drop events.
//
// Why retrying is safe here: every attempt carries an Idempotency-Key header
// derived from the event id. The previous retry loop (207d272) had to be
// reverted (39db4f3) because billing-provider processed every retried
// delivery as a separate charge (1,842 customers were double-charged). With
// an idempotency key the provider can deduplicate retried deliveries, giving
// at-least-once delivery without duplicate side effects.
const MAX_ATTEMPTS = 5;

function idempotencyKeyOf(event) {
  const id = event && (event.id || event.eventId);
  return String(id || JSON.stringify(event));
}

function backoffMs(attempt) {
  // Exponential backoff: 100ms, 200ms, 400ms, 800ms.
  return 2 ** attempt * 100;
}

async function deliver(io, event) {
  const key = idempotencyKeyOf(event);
  for (let attempt = 0; attempt < MAX_ATTEMPTS; attempt += 1) {
    let res = null;
    try {
      res = await io.post('/webhooks/billing', event, {
        headers: { 'Idempotency-Key': key },
      });
    } catch {
      // Network error / timeout — transient; fall through and retry.
      res = null;
    }
    // HTTP 2xx/3xx/4xx are final: a 4xx means the provider rejected the
    // event itself, and retrying it will not help.
    if (res && res.status < 500) return res;
    if (attempt < MAX_ATTEMPTS - 1) await io.sleep(backoffMs(attempt));
  }
  return { status: 502 };
}

module.exports = { deliver };

input.command:
node --check src/dispatcher.js && node -e '
const { deliver } = require("./src/dispatcher.js");

(async () => {
  // 1. Success on first attempt.
  let io = { post: async (p, b, o) => { console.log("post args:", p, JSON.stringify(o)); return { status: 200 }; }, sleep: async () => {} };
  console.log("test1:", await deliver(io, { id: "evt_1" }));

  // 2. Retry on 502s, then success; verify backoff and headers on every call.
  let calls = [];
  io = {
    post: async (p, b, o) => { calls.push({ p, o }); return calls.length < 3 ? { status: 502 } : { status: 200 }; },
    sleep: async (ms) => { calls.push({ sleep: ms }); },
  };
  const r2 = await deliver(io, { id: "evt_2" });
  console.log("test2 result:", JSON.stringify(r2));
  console.log("test2 call plan:", JSON.stringify(calls.map(c => c.sleep ? "sleep " + c.sleep : "post " + c.o.headers["Idempotency-Key"])));

  // 3. 4xx is not retried.
  calls = [];
  io = {
    post: async (p, b, o) => { calls.push(1); return { status: 422 }; },
    sleep: async () => {},
  };
  console.log("test3 result:", JSON.stringify(await deliver(io, { id: "evt_3" })), "posts:", calls.length);

  // 4. All attempts fail -> { status: 502 }.
  calls = [];
  io = {
    post: async () => { calls.push(1); return { status: 502 }; },
    sleep: async () => {},
  };
  console.log("test4 result:", JSON.stringify(await deliver(io, { id: "evt_4" })), "posts:", calls.length);

  // 5. Network error thrown -> retried, then success.
  calls = [];
  io = {
    post: async () => { calls.push(1); if (calls.length < 3) throw new Error("ECONNRESET"); return { status: 204 }; },
    sleep: async () => {},
  };
  console.log("test5 result:", JSON.stringify(await deliver(io, { id: "evt_5" })), "posts:", calls.length);
})().catch(e => { console.error("FAIL", e); process.exit(1); });
'

